class Solution {
public:
    int depthSumInverse(vector<NestedInteger>& nestedList) {
        int unweighted = 0, weighted = 0;
        vector<NestedInteger> curr = nestedList;
        while (!curr.empty()) {
            vector<NestedInteger> nextLevel;
            for (const auto& item : curr) {
                if (item.isInteger()) {
                    unweighted += item.getInteger();
                } else {
                    const auto& sub = item.getList();
                    nextLevel.insert(nextLevel.end(), sub.begin(), sub.end());
                }
            }
            weighted += unweighted;
            curr = move(nextLevel);
        }
        return weighted;
    }
};

class Solution {
    public int depthSumInverse(List<NestedInteger> nestedList) {
        int unweighted = 0, weighted = 0;
        List<NestedInteger> curr = nestedList;
        while (!curr.isEmpty()) {
            List<NestedInteger> nextLevel = new ArrayList<>();
            for (NestedInteger item : curr) {
                if (item.isInteger()) {
                    unweighted += item.getInteger();
                } else {
                    nextLevel.addAll(item.getList());
                }
            }
            weighted += unweighted;
            curr = nextLevel;
        }
        return weighted;
    }
}

/**
 * @param {NestedInteger[]} nestedList
 * @return {number}
 */
var depthSumInverse = function(nestedList) {
    let unweighted = 0;
    let weighted = 0;
    let curr = nestedList;
    while (curr.length > 0) {
        const nextLevel = [];
        for (const item of curr) {
            if (item.isInteger()) {
                unweighted += item.getInteger();
            } else {
                nextLevel.push(...item.getList());
            }
        }
        weighted += unweighted;
        curr = nextLevel;
    }
    return weighted;
};
